INSERT INTO `assessment_questions` VALUES (1,'听力：What does the woman mean? (Audio clip about weekend plans)','[\"A. She likes to travel\", \"B. She works at a hospital\", \"C. She is studying medicine\", \"D. She wants to be a teacher\"]',1,'listening','B1',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(2,'Reading: Choose the best word to fill in the blank.\n\n\"The company has _____ its profits by 20% this year.\"','[\"A. increased\", \"B. decreased\", \"C. maintained\", \"D. predicted\"]',1,'reading','B1',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(3,'Speaking: Describe your favorite food. What is it? Why do you like it? How often do you eat it?','[]',0,'speaking','B1',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(4,'Grammar: Choose the correct sentence.','[\"A. She don\'t like coffee\", \"B. She doesn\'t likes coffee\", \"C. She doesn\'t like coffee\", \"D. She not like coffee\"]',3,'grammar','A2',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(5,'听力：Where does this conversation probably take place? (Audio clip about ordering food)','[\"A. In a library\", \"B. In a restaurant\", \"C. In a hospital\", \"D. In a classroom\"]',2,'listening','A2',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(6,'Reading: What is the main idea of the passage?\n\n\"Climate change has become one of the most pressing issues of our time. Scientists warn that rising temperatures could lead to severe consequences including extreme weather events, sea level rise, and biodiversity loss.\"','[\"A. Weather is unpredictable\", \"B. Climate change poses serious threats\", \"C. Scientists disagree on climate issues\", \"D. Biodiversity is decreasing naturally\"]',2,'reading','B2',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(7,'Speaking: Talk about a memorable trip you have taken. Where did you go? Who did you go with? What made it special?','[]',0,'speaking','B2',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(8,'Grammar: \"If I _____ rich, I would travel around the world.\"','[\"A. am\", \"B. was\", \"C. were\", \"D. be\"]',3,'grammar','B1',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(9,'听力：What is the speaker\'s attitude toward the proposal? (Audio clip about a business plan)','[\"A. Enthusiastic\", \"B. Skeptical\", \"C. Neutral\", \"D. Confused\"]',2,'listening','B2',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(10,'Reading: According to the text, which statement is TRUE?\n\n\"Regular exercise has been shown to improve both physical and mental health. Studies indicate that even 30 minutes of moderate activity per day can reduce the risk of heart disease by up to 30%.\"','[\"A. Exercise only benefits physical health\", \"B. 30 minutes of daily exercise can lower heart disease risk\", \"C. Mental health is unrelated to exercise\", \"D. Only intense exercise provides health benefits\"]',2,'reading','B1',1,'2026-06-24 08:38:56','2026-06-24 08:38:56'),(11,'test question','[]',1,'speaking','A1',1,'2026-06-26 19:36:03','2026-06-26 19:36:03');
