INSERT INTO `faq_entries` VALUES (1,'如何开始使用 Lingolab？','注册账号后，系统会引导您完成英语水平测评。测评完成后即可使用发音评测、AI 对话等全部学习功能。','product_use',1,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(2,'发音评测是如何工作的？','系统使用 AI 语音识别技术分析您的发音，从音素准确度、重音、连读、语调、节奏五个维度进行评分，并给出具体的改进建议。','product_use',2,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(3,'AI 对话支持哪些场景？','目前支持自我介绍、问路、购物、餐厅点餐四个日常场景，以及面试、服务、导游三个角色扮演场景。我们会持续增加更多场景。','product_use',3,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(4,'如何提高我的 CEFR 等级？','坚持每日练习是关键。系统会根据您的薄弱项推荐针对性练习，建议每天完成 3 个学习任务（约 20-30 分钟），持续 2-3 个月通常可以提升一个等级。','study_advice',4,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(5,'录音时提示未检测到语音怎么办？','请检查麦克风权限是否已开启，确保在安静环境中录音，嘴巴距离麦克风 15-30 厘米。如果问题持续，尝试刷新页面或更换浏览器。','tech_issue',5,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(6,'支持哪些浏览器？','系统支持 Chrome 90+、Edge 90+、Firefox 88+ 浏览器。推荐使用 Chrome 以获得最佳体验。移动端请使用浏览器访问，暂不支持微信内置浏览器。','tech_issue',6,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(7,'如何查看我的学习进度？','点击顶部导航的「学习进度」，可以查看雷达图（五维能力）、趋势折线图（分数变化）和日历热力图（打卡记录）。','product_use',7,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(8,'积分和勋章有什么用？','积分反映您的学习投入度，勋章是对特定成就的认可。完成每日任务、闯关、配音挑战都可以获得积分和勋章。','product_use',8,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(9,'可以退款吗？','Lingolab 基础功能完全免费。如有付费项目需要退款，请发送邮件至 support@lingolab.ai 说明情况，我们会在 3 个工作日内处理。','refund',9,1,'2026-06-26 08:19:30','2026-06-26 08:19:30'),(10,'如何联系人工客服？','如果智能客服无法解决您的问题，请发送邮件至 support@lingolab.ai，我们的客服团队会在 24 小时内回复。','general',10,1,'2026-06-26 08:19:30','2026-06-26 08:19:30');
/*!40000 ALTER TABLE `faq_entries` ENABLE KEYS */;
UNLOCK TABLES;

